.tree { display: block; width: 100%; min-width: 0; box-sizing: border-box; padding: 6px 8px 8px; border: 1px solid var(--border); border-radius: 16px; background: var(--surface); color: var(--foreground); overflow: hidden; }
/* Rows clip only while their height animates (Motion sets overflow), so the selection can glide between them unclipped. */
.row { position: relative; display: flow-root; min-width: 0; height: 38px; }
.item { position: relative; display: flex; width: 100%; min-width: 0; height: 36px; margin-top: 2px; align-items: center; gap: 8px; padding: 0 10px; padding-left: calc(10px + (var(--tree-depth) - 1) * 18px); border: 0; border-radius: 10px; background: transparent; color: var(--text-secondary); font: inherit; font-size: var(--text-sm); line-height: 1; text-align: left; cursor: pointer; outline: none; transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard); }
/* Selection changes color only; a heavier weight would reflow the label. */
.item[aria-selected="true"] { color: var(--foreground); }
/* One ring drawn inside the row, so it clears the tree's clipped edge; the global button outline would add a second ring outside it. */
.item:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: -2px; }
.selection { position: absolute; inset: 0; z-index: 0; border-radius: 10px; background: var(--surface-muted); }
.branch { position: absolute; top: 4px; bottom: 4px; left: calc(18px + (var(--tree-depth) - 2) * 18px); z-index: 1; width: 1px; background: var(--border); transform-origin: top; pointer-events: none; }
.disclosure, .icon, .label { position: relative; z-index: 1; }
.disclosure { display: grid; width: 14px; height: 16px; flex: 0 0 14px; place-items: center; color: var(--text-muted); }
.icon { display: grid; width: 16px; height: 16px; flex: 0 0 16px; place-items: center; color: var(--text-muted); transition: color var(--duration-fast) var(--ease-standard); }
.folder { color: var(--text-secondary); }
.item[aria-expanded="true"] .folder, .item[aria-selected="true"] .folder { color: var(--foreground); }
.folderGlyph { position: absolute; inset: 0; display: grid; place-items: center; }
.typescript { color: color-mix(in oklch, #3178c6 78%, var(--foreground)); }
.stylesheet { color: color-mix(in oklch, #8b6ace 73%, var(--foreground)); }
.markdown { color: color-mix(in oklch, #38896b 74%, var(--foreground)); }
.json { color: color-mix(in oklch, #c48637 78%, var(--foreground)); }
.label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
@media (hover: hover) and (pointer: fine) { .item:hover { background: var(--surface-muted); color: var(--foreground); } }
@media (prefers-reduced-motion: reduce) { .item, .icon { transition: none; } }
